function LINEAR_SEARCH(A, target):
    for index from 0 to length(A) - 1:
        if A[index] == target:
            return index
    return -1

function BINARY_SEARCH(A, target):
    left = 0
    right = length(A) - 1
    while left <= right:
        mid = left + floor((right - left) / 2)
        if A[mid] == target:
            return mid
        else if A[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

